import React, { useEffect, useState } from "react";
import DashboardLayout from "../components/DashboardLayout";
import ConfirmDeleteModal from "../components/ConfirmDeleteModal";
import { menuService } from "../services/menuService";
import { useAuth } from "../context/AuthContext";

const BLANK = { name: "", category: "Starters", price: "", description: "" };
const CATEGORIES = ["Starters", "Main Course", "Desserts", "Beverages"];

export default function Menu() {
  const { user } = useAuth();
  const [items, setItems] = useState([]);
  const [form, setForm] = useState(BLANK);
  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [category, setCategory] = useState("All");
  const [deletingItem, setDeletingItem] = useState(null);
  const [deleteLoading, setDeleteLoading] = useState(false);

  const canManage = user?.role === "admin" || user?.role === "staff";

  function refresh() {
    menuService.getAll().then(setItems);
  }
  useEffect(() => {
    refresh();
    const handleUpdate = () => refresh();
    window.addEventListener("db_updated", handleUpdate);
    window.addEventListener("storage", handleUpdate);
    window.addEventListener("focus", handleUpdate);
    return () => {
      window.removeEventListener("db_updated", handleUpdate);
      window.removeEventListener("storage", handleUpdate);
      window.removeEventListener("focus", handleUpdate);
    };
  }, []);

  function update(field, value) {
    setForm((f) => ({ ...f, [field]: value }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const payload = { ...form, price: Number(form.price) };
    if (editingId) await menuService.update(editingId, payload);
    else await menuService.create(payload);
    setForm(BLANK);
    setEditingId(null);
    setShowForm(false);
    refresh();
  }

  function startEdit(item) {
    setForm(item);
    setEditingId(item.id);
    setShowForm(true);
  }

  async function handleConfirmDelete() {
    if (!deletingItem) return;
    setDeleteLoading(true);
    try {
      await menuService.remove(deletingItem.id);
      refresh();
    } finally {
      setDeleteLoading(false);
      setDeletingItem(null);
    }
  }

  const visible = category === "All" ? items : items.filter((i) => i.category === category);

  return (
    <DashboardLayout title="Menu">
      <div className="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3">
        <select className="form-select" style={{ width: 200 }} value={category} onChange={(e) => setCategory(e.target.value)}>
          <option>All</option>
          {CATEGORIES.map((c) => <option key={c}>{c}</option>)}
        </select>
        {canManage && (
          <button className="btn btn-brass d-flex align-items-center gap-2 fw-semibold" onClick={() => { setForm(BLANK); setEditingId(null); setShowForm((v) => !v); }}>
            {showForm ? "✕ Close" : "➕ Add menu item"}
          </button>
        )}
      </div>

      {showForm && canManage && (
        <form onSubmit={handleSubmit} className="card-plain p-3 mb-4">
          <div className="row g-2">
            <div className="col-12 col-md-4">
              <label className="mono" style={{ fontSize: "0.75rem" }}>Item name</label>
              <input className="form-control" required value={form.name} onChange={(e) => update("name", e.target.value)} />
            </div>
            <div className="col-6 col-md-3">
              <label className="mono" style={{ fontSize: "0.75rem" }}>Category</label>
              <select className="form-select" value={form.category} onChange={(e) => update("category", e.target.value)}>
                {CATEGORIES.map((c) => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div className="col-6 col-md-2">
              <label className="mono" style={{ fontSize: "0.75rem" }}>Price (₹)</label>
              <input type="number" min={0} className="form-control" required value={form.price} onChange={(e) => update("price", e.target.value)} />
            </div>
            <div className="col-12 col-md-3">
              <label className="mono" style={{ fontSize: "0.75rem" }}>Description</label>
              <input className="form-control" value={form.description} onChange={(e) => update("description", e.target.value)} />
            </div>
          </div>
          <button className="btn btn-brass mt-3 fw-semibold" style={{ width: 160 }}>{editingId ? "Save Changes" : "Add Item"}</button>
        </form>
      )}

      <div className="row g-3">
        {visible.map((item) => (
          <div className="col-12 col-md-6 col-lg-4" key={item.id}>
            <div className="card-plain p-3 h-100 d-flex flex-column">
              <div className="d-flex justify-content-between align-items-center mb-1">
                <strong className="fs-6">{item.name}</strong>
                <span className="mono fw-bold" style={{ fontSize: "1.05rem" }}>₹{item.price}</span>
              </div>
              <span className="eyebrow mb-2">{item.category}</span>
              <p className="text-secondary flex-grow-1" style={{ fontSize: "0.88rem" }}>{item.description}</p>
              {canManage && (
                <div className="d-flex gap-2 pt-2 mt-2 border-top" style={{ borderColor: "var(--line)" }}>
                  <button className="btn btn-sm tbl-edit-btn px-3 d-flex align-items-center gap-1" onClick={() => startEdit(item)}>
                    ✏️ Edit
                  </button>
                  <button className="btn btn-sm tbl-delete-btn px-3 d-flex align-items-center gap-1" onClick={() => setDeletingItem(item)}>
                    🗑️ Delete
                  </button>
                </div>
              )}
            </div>
          </div>
        ))}
        {visible.length === 0 && <p className="text-secondary">No items in this category.</p>}
      </div>

      {/* Modern Custom Delete Confirmation Popup */}
      <ConfirmDeleteModal
        isOpen={!!deletingItem}
        title={`Delete "${deletingItem?.name}"?`}
        message={
          <>
            Are you sure you want to remove <strong className="text-dark">{deletingItem?.name}</strong> from the menu? This action cannot be undone.
          </>
        }
        onConfirm={handleConfirmDelete}
        onClose={() => setDeletingItem(null)}
        loading={deleteLoading}
      />
    </DashboardLayout>
  );
}
